161	    InputStream responseBody() throws IOException {
162	        if (hRes == null) throw new IllegalStateException("Not yet executed");
163	        return hRes.body();
164	    }
165	
166	    @Override
167	    void safeClose() {
168	        if (hRes != null) {
169	            InputStream body = hRes.body();
170	            if (body != null) {
171	                try {
172	                    body.close();
173	                } catch (IOException ignored) {}
174	            }
175	            hRes = null;
176	        }
177	    }
