226	    private static final class ClientState {
227	        final HttpClient client;
228	        final @Nullable RequestAuthenticator authenticator;
229	        final SSLContext sslContext;
230	
231	        ClientState(@Nullable RequestAuthenticator authenticator, SSLContext sslContext) {
232	            this.client = newClient(authenticator, sslContext);
233	            this.authenticator = authenticator;
234	            this.sslContext = sslContext;
235	        }
236	
237	        boolean matches(@Nullable RequestAuthenticator authenticator, SSLContext sslContext) {
238	            return this.authenticator == authenticator && this.sslContext == sslContext;
239	        }
240	    }
241	}
