89	        void assertMonotonic() {
90	            int lastProcessed = -1;
91	            float lastPercent = -1f;
92	            for (Event e : events) {
93	                assertTrue(e.processed >= lastProcessed, "processed went backwards: " + lastProcessed + " -> " + e.processed);
94	                assertTrue(e.percent >= lastPercent, "percent went backwards: " + lastPercent + " -> " + e.percent);
95	                lastProcessed = e.processed;
96	                lastPercent = e.percent;
97	            }
98	        }
