6	import java.io.FilterInputStream;
7	import java.io.IOException;
8	import java.io.InputStream;
9	
10	import static org.jsoup.internal.SharedConstants.DefaultBufferSize;
11	
12	/**
13	 A simple implementation of a buffered input stream, in which we can control the byte[] buffer to recycle it. Not safe for
14	 use between threads; no sync or locks. The buffer is borrowed on initial demand in fill.
15	 @since 1.18.2
16	 */
17	class SimpleBufferedInput extends FilterInputStream {
18	    static final int BufferSize = DefaultBufferSize;
19	    static final SoftPool<byte[]> BufferPool = new SoftPool<>(() -> new byte[BufferSize]);
20	    private boolean capped;                 // whether pulls from the underlying stream are capped
21	    private int capRemaining = Integer.MAX_VALUE; // how many bytes we are allowed to pull from the underlying stream
22	    private int lookahead = -1;             // one byte retained when probing beyond a cap
23	
24	    private byte @Nullable [] byteBuf; // the byte buffer; recycled via SoftPool. Created in fill if required
25	    private int bufPos;
26	    private int bufLength;
27	    private int bufMark = -1; // mark set by ControllableInputStream; -1 when unset
28	    private boolean inReadFully = false; // true when the underlying inputstream has been read fully
29	
30	    SimpleBufferedInput(@Nullable InputStream in) {
31	        super(in);
32	        if (in == null) inReadFully = true; // effectively an empty stream
33	    }
34	
35	    @Override
36	    public int read() throws IOException {
37	        if (bufPos >= bufLength) {
38	            fill();
39	            if (bufPos >= bufLength)
