import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class ReproTest {
    static final class Ev { int p; int t; float pct; Ev(int p,int t,float pct){this.p=p;this.t=t;this.pct=pct;} public String toString(){return "("+p+","+t+","+pct+")";} }

    private static long completions(List<Ev> evs){ return evs.stream().filter(e->e.pct==100f).count(); }

    @Test void exactKnownLengthCompletes() throws IOException {
        int len=100;
        List<Ev> evs = new ArrayList<>();
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(new byte[len]), 8192, len);
        in.onProgress(len, true, (Progress<ControllableInputStream>)(p,t,pct,c)->evs.add(new Ev(p,t,pct)), in);
        ByteBuffer bb = DataUtil.readToByteBuffer(in, len);
        assertEquals(len, bb.remaining());
        in.close();
        System.out.println("exact: "+evs);
        assertEquals(1, completions(evs), "exact-cap known length completes once");
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertEquals(100, last.t); assertEquals(100f, last.pct);
    }

    @Test void truncationDoesNotCompleteAndLosesNoBytes() throws IOException {
        int dataLen=150, cap=100;
        byte[] data=new byte[dataLen];
        for (int i=0;i<dataLen;i++) data[i]=(byte)(i%251+1);
        List<Ev> evs = new ArrayList<>();
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 8192, cap);
        in.onProgress(dataLen, true, (Progress<ControllableInputStream>)(p,t,pct,c)->evs.add(new Ev(p,t,pct)), in);

        ByteBuffer bb = DataUtil.readToByteBuffer(in, cap);
        assertEquals(cap, bb.remaining());
        assertEquals(0, completions(evs), "a truncated entity does not complete at the cap");
        int eventsAtCap = evs.size();

        // lifting the cap and draining the real remainder must not lose the probed byte, and completes at genuine EOF
        in.max(0);
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf=new byte[4096]; int r;
        while ((r=in.read(buf))!=-1) bos.write(buf,0,r);
        byte[] tail=bos.toByteArray();
        assertEquals(dataLen-cap, tail.length, "the probed byte plus the rest are all retained");
        byte firstAfterCap = bb.get(bb.position()-0)==0? data[0] : data[0]; // sanity no-op
        assertEquals(data[cap], tail[0], "the retained lookahead byte is the first post-cap byte, no data lost");
        in.close();
        System.out.println("trunc: capEvents="+evs.subList(0,eventsAtCap)+" all="+evs);
        assertEquals(1, completions(evs), "completes exactly once, only at the genuine end after the cap is lifted");
    }

