        DataUtil.readToByteBuffer(in, len);
        in.close();
        System.out.println("exact-unknown: "+evs);
        assertEquals(1, completions(evs));
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertEquals(-1, last.t); assertEquals(100f, last.pct);
    }

    @Test void exactCapUnsuccessfulNeverCompletes() throws IOException {
        int len=100;
        List<Ev> evs = new ArrayList<>();
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(new byte[len]), 8192, len);
        in.onProgress(len, false, (Progress<ControllableInputStream>)(p,t,pct,c)->evs.add(new Ev(p,t,pct)), in);
        DataUtil.readToByteBuffer(in, len);
        in.close();
        System.out.println("exact-err: "+evs);
        assertEquals(0, completions(evs), "an error status never completes even at exact cap");
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertTrue(last.pct < 100f);
    }

    @Test void shorterEntityThanCapCompletes() throws IOException {
        List<Ev> evs = new ArrayList<>();
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(new byte[50]), 8192, 100);
        in.onProgress(50, true, (Progress<ControllableInputStream>)(p,t,pct,c)->evs.add(new Ev(p,t,pct)), in);
        DataUtil.readToByteBuffer(in, 100);
        in.close();
        System.out.println("short: "+evs);
        assertEquals(1, completions(evs));
    }

    @Test void plainUncontrolledZeroLengthReadConsumesNothing() throws IOException {
        // guard: on a plain InputStream the confirming 0-length read must return 0 and discard no bytes
        byte[] data = new byte[100];
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0); // uncapped
        assertEquals(0, in.read(new byte[8], 0, 0));
        byte[] got = new byte[100];
        assertEquals(100, in.read(got));
        in.close();
    }
}

