package org.jsoup.internal;

import org.jsoup.helper.DataUtil;
import org.jsoup.Progress;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class ReproTest {
    static final class Ev { int p; int t; float pct; Ev(int p,int t,float pct){this.p=p;this.t=t;this.pct=pct;} public String toString(){return "("+p+","+t+","+pct+")";} }

    private static List<Ev> run(int dataLen, Integer declaredLen, int cap, boolean successful) throws IOException {
        byte[] data = new byte[dataLen];
        for (int i=0;i<dataLen;i++) data[i]=(byte)(i%251+1);
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 8192, cap);
        List<Ev> evs = new ArrayList<>();
        Progress<ControllableInputStream> cb = (p,t,pct,c)->evs.add(new Ev(p,t,pct));
        int dl = declaredLen==null?-1:declaredLen;
        in.onProgress(dl, successful, cb, in);
        ByteBuffer bb = DataUtil.readToByteBuffer(in, cap);
        // after a truncating read, the retained lookahead must not corrupt the rest: lift cap and drain remainder
        if (cap > 0 && dataLen > cap) {
            in.max(0);
            byte[] rest = new byte[dataLen];
            // verify the probed byte is preserved: total logical bytes delivered must equal dataLen
            java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
            byte[] buf = new byte[4096]; int r;
            while ((r=in.read(buf))!=-1) bos.write(buf,0,r);
            byte[] all = bos.toByteArray();
            byte[] combined = new byte[cap + all.length];
            System.arraycopy(bb.array(), bb.arrayOffset(), combined, 0, cap);
            System.arraycopy(all, 0, combined, cap, all.length);
            assertEquals(dataLen, combined.length, "no bytes lost around the cap probe");
            for (int i=0;i<dataLen;i++) assertEquals(data[i], combined[i], "byte integrity at "+i);
        }
        in.close();
        return evs;
    }

    private long completions(List<Ev> evs){ return evs.stream().filter(e->e.pct==100f).count(); }

    @Test void exactKnownLengthCompletes() throws IOException {
        List<Ev> evs = run(100, 100, 100, true);
        System.out.println("exact: "+evs);
        assertEquals(1, completions(evs), "exact-cap known length completes once");
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertEquals(100, last.t); assertEquals(100f, last.pct);
    }

    @Test void truncationDoesNotCompleteAndLosesNoBytes() throws IOException {
        List<Ev> evs = run(150, 150, 100, true);
        System.out.println("trunc: "+evs);
        assertEquals(0, completions(evs), "a truncated entity never completes");
    }

    @Test void exactUnknownLengthCompletes() throws IOException {
        List<Ev> evs = run(100, null, 100, true);
        System.out.println("exact-unknown: "+evs);
        assertEquals(1, completions(evs));
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertEquals(-1, last.t); assertEquals(100f, last.pct);
    }

    @Test void exactCapUnsuccessfulNeverCompletes() throws IOException {
        List<Ev> evs = run(100, 100, 100, false);
        System.out.println("exact-err: "+evs);
        assertEquals(0, completions(evs), "an error status never completes even at exact cap");
        Ev last = evs.get(evs.size()-1);
        assertEquals(100, last.p); assertTrue(last.pct < 100f);
    }

    @Test void shorterEntityThanCapCompletes() throws IOException {
        List<Ev> evs = run(50, 50, 100, true); // entity ends before cap; EOF read confirms
        System.out.println("short: "+evs);
        assertEquals(1, completions(evs));
    }
}

